package apitypes

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// This fixture is also decoded by the agent. Keep it generated by the API DTO,
// not a separately authored approximation of the wire.
func TestSemanticCandidateWire(t *testing.T) {
	rawSource := []byte("require é\x00\r\n")
	sum := sha256.Sum256(rawSource)
	hash := hex.EncodeToString(sum[:])
	candidate := SemanticCandidate{
		CandidateIdentityVersion: "semantic_v1", Revision: 1, Digest: strings.Repeat("b", 64),
		Sources:  []SemanticSourceRef{{ID: "issue:1230", Kind: "issue", Hash: hash, Provenance: "example/repo:issue:1230", Completeness: "complete"}},
		PlanHash: strings.Repeat("b", 64), SourceOutcome: "complete",
		Criteria: []SemanticCriterion{{ID: "12345678-1234-4234-8234-123456789abc", ProposedSemanticCriterion: ProposedSemanticCriterion{
			MilestoneID: "M1", Kind: "code", Text: "Preserve source bytes", DoneWhen: "The captured bytes are identical",
			Citations:            []SemanticCitation{{SourceID: "issue:1230", Hash: hash, Start: 0, End: len(rawSource)}},
			EvidenceRequirements: []SemanticEvidence{{Description: "Focused test", Path: "agent/test/semantic-plan.test.ts"}},
		}}},
	}
	encoded, err := json.Marshal(candidate)
	if err != nil {
		t.Fatal(err)
	}
	expected, err := os.ReadFile("../../../fixtures/semantic-plan/candidate.json")
	if err != nil || !bytes.Equal(bytes.TrimSpace(expected), encoded) {
		t.Fatalf("API_WIRE_FIXTURE=%s\nfixture mismatch: %v", encoded, err)
	}
	var decoded SemanticCandidate
	decoder := json.NewDecoder(bytes.NewReader(expected))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&decoded); err != nil {
		t.Fatal(err)
	}
	again, err := json.Marshal(decoded)
	if err != nil || !bytes.Equal(encoded, again) {
		t.Fatalf("round trip differs: %v", err)
	}
}
